  static final Map<String, Set<String>> _recordedAudioByLang = {
    'hi': _hiAudioKeys,
    'en': _enAudioKeys,
    'ta': _taAudioKeys,
    'gu': _guAudioKeys,
  };

  /// Whether a recorded audio clip exists for [key] in [langCode].
  static bool hasRecordedAudio(String key, String langCode) {
    final lang = langCode.trim().toLowerCase();
    final cleanKey = key.trim();
    if (cleanKey.isEmpty) return false;
    final resolvedKey = resolveAudioKey(cleanKey);
    final baseKey = resolvedKey.replaceAll(
      RegExp(r'_(en|ta|hi|kn|te|mr|gu)$', caseSensitive: false),
      '',
    );
    final keys = _recordedAudioByLang[lang];
    if (keys == null) return false;
    return keys.contains(cleanKey) ||
        keys.contains(resolvedKey) ||
        keys.contains(baseKey) ||
        keys.contains('${cleanKey}_$lang') ||
        keys.contains('${baseKey}_$lang');
  }

  static bool contains(String key) =>
      _en.containsKey(key) || _audioAliases.containsKey(key);

  static Iterable<String> get keys => _en.keys;

