    'onb_pre_folic_acid': 'ஒரு முக்கியமான விஷயம். இப்பவே folic acid எடுக்க ஆரம்பிங்க — நான் வர்றதுக்கு முன்னாடியே அது என்ன பாதுகாக்கும்.',
