    'onb_pre_habits': 'நல்ல சாப்பாடு, நல்ல தூக்கம், புகையிலை மது எதுவும் வேணாம். இப்படித்தான் எனக்காக தயாராகணும்.',
    'onb_pre_habits_mom': 'நல்ல சாப்பாடு, நல்ல தூக்கம், புகையிலை மது எதுவும் வேணாம். இப்படித்தான் எனக்காக தயாராகணும்.',
    'onb_pre_home_first_question': 'ஆரம்பிக்கலாமா? இன்னைக்கு நீங்க எப்படி இருக்கீங்க?',
    'onb_pre_home_first_question_mom': 'ஆரம்பிக்கலாமா? இன்னைக்கு நீங்க எப்படி இருக்கீங்க?',
    'onb_pre_home_waiting': 'நான் உங்க கிட்ட வர காத்துட்டு இருக்கேன். சேர்ந்து தயாராகலாம்.',
