    'onb_pre_kids': 'உங்களுக்கு ஏற்கனவே குழந்தைங்க இருக்காங்களா?',
    'onb_pre_kids_mom': 'உங்களுக்கு ஏற்கனவே குழந்தைங்க இருக்காங்களா?',
    'onb_pre_partner': 'உங்க துணைய பத்தி சொல்லுங்க, ரெண்டு பேரும் சேர்ந்து எனக்காக தயாராகலாம்.',
