    'onb_preg_edd_countdown_soon': 'இன்னும் ரொம்ப சீக்கிரம். எந்த நாளும் நான் உங்க கையில இருப்பேன்.',
    'onb_preg_edd_countdown_soon_mom': 'இன்னும் ரொம்ப சீக்கிரம். எந்த நாளும் நான் உங்க கையில இருப்பேன்.',
