    'onb_preg_lmp': 'அம்மா, உங்க கடைசி period எப்ப ஆரம்பிச்சுது?',
    'onb_preg_lmp_confirm': 'ஆச்சு! இப்ப நாம எந்த வாரத்துல இருக்கோம்னு தெரிஞ்சிடுச்சு.',
