    'onb_preg_lmp_unknown_mom': 'சரியான தேதி ஞாபகம் இல்லைன்னா, கிட்டத்தட்ட எது சரியோ அத சொல்லுங்க. டாக்டர் scan ல உறுதி ஆயிடும்.',
