    'onb_preg_partner_skip': 'பரவால்ல. எப்ப வேணும்னாலும் சேர்க்கலாம்.',
    'onb_preg_partner_skip_mom': 'பரவால்ல. எப்ப வேணும்னாலும் சேர்க்கலாம்.',
