    'preg_kids_no_mom': 'அப்ப நான்தான் உங்க முதல் குழந்தை! இது இன்னும் ஸ்பெஷல்.',
    'preg_kids_no_mom_ta': 'அப்ப நான்தான் உங்க முதல் குழந்தை! இது இன்னும் ஸ்பெஷல்.',
    'preg_kids_yes': 'எவ்ளோ சந்தோஷம்! அப்ப நான் தனியா இல்ல.',
    'preg_kids_yes_mom': 'எவ்ளோ சந்தோஷம்! அப்ப நான் தனியா இல்ல.',
    'preg_kids_yes_mom_ta': 'எவ்ளோ சந்தோஷம்! அப்ப நான் தனியா இல்ல.',
    'preg_lmp': 'அம்மா, உங்க கடைசி period எப்ப ஆரம்பிச்சுது?',
    'preg_lmp_confirm': 'ஆச்சு! இப்ப நாம எந்த வாரத்துல இருக்கோம்னு தெரிஞ்சிடுச்சு.',
    'preg_lmp_confirm_mom': 'ஆச்சு! இப்ப நாம எந்த வாரத்துல இருக்கோம்னு தெரிஞ்சிடுச்சு.',
    'preg_lmp_confirm_mom_ta': 'ஆச்சு! இப்ப நாம எந்த வாரத்துல இருக்கோம்னு தெரிஞ்சிடுச்சு.',
    'preg_lmp_future_error': 'இந்த தேதி இன்னைக்கு அப்புறமா இருக்கு. ஒரு தடவ பாருங்க.',
    'preg_lmp_future_error_mom': 'இந்த தேதி இன்னைக்கு அப்புறமா இருக்கு. ஒரு தடவ பாருங்க.',
    'preg_lmp_future_error_mom_ta': 'இந்த தேதி இன்னைக்கு அப்புறமா இருக்கு. ஒரு தடவ பாருங்க.',
    'preg_lmp_mom': 'அம்மா, உங்க கடைசி period எப்ப ஆரம்பிச்சுது?',
    'preg_lmp_mom_ta': 'அம்மா, உங்க கடைசி period எப்ப ஆரம்பிச்சுது?',
    'preg_lmp_stage_t1': 'நாம ஆரம்ப மாசங்கள்ல இருக்கோம். நான் இன்னும் ரொம்ப சின்னதா இருக்கேன்.',
    'preg_lmp_stage_t1_mom': 'நாம ஆரம்ப மாசங்கள்ல இருக்கோம். நான் இன்னும் ரொம்ப சின்னதா இருக்கேன்.',
    'preg_lmp_stage_t1_mom_ta': 'நாம ஆரம்ப மாசங்கள்ல இருக்கோம். நான் இன்னும் ரொம்ப சின்னதா இருக்கேன்.',
    'preg_lmp_stage_t2': 'இப்ப நாம நடு மாசங்கள்ல இருக்கோம். இந்த பகுதி பொதுவா சுலபமா இருக்கும்.',
    'preg_lmp_stage_t2_mom': 'இப்ப நாம நடு மாசங்கள்ல இருக்கோம். இந்த பகுதி பொதுவா சுலபமா இருக்கும்.',
    'preg_lmp_stage_t2_mom_ta': 'இப்ப நாம நடு மாசங்கள்ல இருக்கோம். இந்த பகுதி பொதுவா சுலபமா இருக்கும்.',
    'preg_lmp_stage_t3': 'நாம கடைசி மாசங்களுக்கு வந்துட்டோம். இன்னும் கொஞ்ச நாள் தான்.',
    'preg_lmp_stage_t3_mom': 'நாம கடைசி மாசங்களுக்கு வந்துட்டோம். இன்னும் கொஞ்ச நாள் தான்.',
    'preg_lmp_stage_t3_mom_ta': 'நாம கடைசி மாசங்களுக்கு வந்துட்டோம். இன்னும் கொஞ்ச நாள் தான்.',
    'preg_lmp_unknown': 'சரியான தேதி ஞாபகம் இல்லைன்னா, கிட்டத்தட்ட எது சரியோ அத சொல்லுங்க. டாக்டர் scan ல உறுதி ஆயிடும்.',
    'preg_lmp_unknown_mom': 'சரியான தேதி ஞாபகம் இல்லைன்னா, கிட்டத்தட்ட எது சரியோ அத சொல்லுங்க. டாக்டர் scan ல உறுதி ஆயிடும்.',
    'preg_lmp_unknown_mom_ta': 'சரியான தேதி ஞாபகம் இல்லைன்னா, கிட்டத்தட்ட எது சரியோ அத சொல்லுங்க. டாக்டர் scan ல உறுதி ஆயிடும்.',
    'preg_lmp_why': 'இத ஏன் கேக்குறேன்னா, நாம எப்ப சந்திப்போம்னு இதுல இருந்துதான் தெரியும்.',
    'preg_lmp_why_mom': 'இத ஏன் கேக்குறேன்னா, நாம எப்ப சந்திப்போம்னு இதுல இருந்துதான் தெரியும்.',
    'preg_lmp_why_mom_ta': 'இத ஏன் கேக்குறேன்னா, நாம எப்ப சந்திப்போம்னு இதுல இருந்துதான் தெரியும்.',
    'preg_partner': 'அப்பாவ பத்தி சொல்லுங்க, அவரும் நம்ம பயணத்துல சேரட்டும்.',
    'preg_partner_dad': 'அம்மாவ பத்தி சொல்லுங்க, நாம சேர்ந்து அவங்கள பாத்துக்கலாம்.',
    'preg_partner_dad_ta': 'அம்மாவ பத்தி சொல்லுங்க, நாம சேர்ந்து அவங்கள பாத்துக்கலாம்.',
    'preg_partner_mom': 'அப்பாவ பத்தி சொல்லுங்க, அவரும் நம்ம பயணத்துல சேரட்டும்.',
    'preg_partner_mom_ta': 'அப்பாவ பத்தி சொல்லுங்க, அவரும் நம்ம பயணத்துல சேரட்டும்.',
    'preg_partner_saved': 'இப்ப அப்பாவும் நம்ம கூட இருக்காரு.',
    'preg_partner_saved_mom': 'இப்ப அப்பாவும் நம்ம கூட இருக்காரு.',
    'preg_partner_saved_mom_ta': 'இப்ப அப்பாவும் நம்ம கூட இருக்காரு.',
    'preg_partner_skip': 'பரவால்ல. எப்ப வேணும்னாலும் சேர்க்கலாம்.',
    'preg_partner_skip_mom': 'பரவால்ல. எப்ப வேணும்னாலும் சேர்க்கலாம்.',
    'preg_partner_skip_mom_ta': 'பரவால்ல. எப்ப வேணும்னாலும் சேர்க்கலாம்.',
    'preg_setup_done': 'எல்லாம் ரெடி. வாங்க, வீட்டுக்கு போலாம்.',
    'preg_setup_done_mom': 'எல்லாம் ரெடி. வாங்க, வீட்டுக்கு போலாம்.',
    'preg_setup_done_mom_ta': 'எல்லாம் ரெடி. வாங்க, வீட்டுக்கு போலாம்.',
    'scr_agents_mom': 'ஒவ்வொரு வசதியும் ஒரு உதவியாளர் மாதிரி, அம்மா. AlloCry, Kick Counter, Feeding Tracker, Daily Activity — ஒண்ண தொடுங்க, இல்லன்னா திறக்கச் சொல்லி என்கிட்ட கேளுங்க.',
    'scr_allobot_chat_mom': 'இங்க நாம பேசலாம், அம்மா. எல்லாத்தையும் நான் ஞாபகம் வெச்சுக்குவேன், நீங்க திரும்பத் திரும்ப சொல்லவே வேண்டாம்.',
    'scr_allobot_settings_mom': 'நான் ரொம்ப வேகமா இல்ல ரொம்ப மெதுவா பேசினா, இங்க சரி பண்ணிக்குங்க, அம்மா.',
    'scr_allocry_mom': 'நான் அழும்போது, போன என் பக்கத்துல பிடிங்க, அம்மா. எனக்கு என்ன வேணும்னு புரிஞ்சுக்க நான் உதவுவேன்.',
    'scr_ask_allo_mom': 'மனசுல இருக்குறத கேளுங்க, அம்மா. என்ன பத்தி, உங்க உடம்ப பத்தி, எது வேணும்னாலும்.',
    'scr_baby_milestones_mom': 'ஒவ்வொரு milestone-லயும் நான் எவ்வளவு வளர்ந்திருக்கேன்னு இங்க பாக்கலாம், அம்மா.',
    'scr_baby_vaccines_mom': 'உங்க ஊசியும் என் ஊசியும் இங்க இருக்கு, அம்மா. ரெண்டு பேரையும் இது காப்பாத்தும்.',
    'scr_daily_activity_mom': 'இன்னைக்கு இதுவரைக்கும் எப்படி போயிருக்குன்னு இங்க இருக்கு, அம்மா — என்ன முடிஞ்சுது, அடுத்து என்ன, இன்னும் என்ன பாக்கி.',
    'scr_feeding_tracker_mom': 'அம்மா, இது உங்க feeding tracker. ஒவ்வொரு தடவ பால் கொடுக்குறதையும் இங்க குறிச்சு வைக்கலாம், அப்போ நாள் முழுக்க என் feeding எப்படி இருக்குன்னு பாக்கலாம்.',
    'scr_feeds_mom': 'உங்களுக்கான சின்ன டிப்ஸ், சுலபமான ரெசிபி, அம்மா. வேலை செய்யும்போதே கேளுங்க.',
    'scr_home_care_mom': 'இன்னைக்கு செய்ய வேண்டிய சின்ன விஷயங்க இங்க இருக்கு, அம்மா. ஒவ்வொண்ணா செய்யலாம்.',
    'scr_home_mom': 'இன்னைக்கு எல்லாமே இங்கதான் இருக்கு, அம்மா. சாப்பாடு, தண்ணி, ஓய்வு — நான் பாத்துக்குவேன்.',
    'scr_home_nutrition_mom': 'இன்னைக்கு நீங்க சாப்பிடுறது குடிக்கிறது எல்லாம் இங்க வரும், அம்மா. சொன்னா போதும்.',
    'scr_home_vitals_mom': 'உங்க உடம்போட எல்லா ரீடிங்கும் இங்க இருக்கு, அம்மா. நடை, இதயம், தூக்கம்.',
    'scr_kick_counter_mom': 'என் உதைகள சேர்ந்து எண்ணலாம், அம்மா. நான் அசையுறது தெரியும்போதெல்லாம் தொடுங்க.',
    'scr_my_cycle_phase_mom': 'இப்போ உங்க உடம்புல என்ன நடக்குதுன்னு இங்க இருக்கு, அம்மா. எது நல்லது, எத தவிர்க்கணும்னு சொல்றேன். நீங்க பதிவு பண்ற ஒவ்வொரு period-ஐயும் ஞாபகம் வெச்சுக்குவேன்.',
    'scr_my_cycle_tracker_mom': 'இது நம்ம cycle, அம்மா. நாட்கள நான் எண்ணிக்கிறேன், உங்க fertile days-ஐ குறிச்சு வைக்கிறேன், அடுத்த period எப்போன்னு சொல்றேன்.',
    'scr_my_health_mom': 'அம்மா, உங்க health எல்லாம் ஒரே இடத்துல இருக்கு — தூக்கம், இதயம், activity, சாப்பாடு. இங்க நாம சேர்ந்து பாத்துக்கலாம்.',
    'scr_my_prescriptions_mom': 'உங்க மருந்துகள் எல்லாம் இங்க இருக்கு, அம்மா. ஒவ்வொரு dose நேரத்துக்கும் நான் ஞாபகப்படுத்துவேன், ஒண்ணும் விட்டுப்போகாது.',
    'scr_my_profile_mom': 'உங்க விவரம் எல்லாம் இங்க இருக்கு, அம்மா. சரியில்லாதத மாத்திக்குங்க.',
    'scr_my_reports_mom': 'உங்க reports எல்லாம் இங்க பத்திரமா இருக்கு, அம்மா. எப்போ வேணும்னாலும் பாக்கலாம், உங்க சொந்த Drive-லயும் backup பண்ணிக்கலாம்.',
    'scr_my_vitals_mom': 'உங்க உடம்போட எல்லா ரீடிங்கும் இங்க இருக்கு, அம்மா. நடை, இதயம், தூக்கம்.',
    'scr_new_baby_profile_mom': 'இது முழுக்க என்னப் பத்திதான், அம்மா — என் விவரங்கள், என் தடுப்பூசிகள், என் milestones. மேலும் பாக்க எதையாவது தொடுங்க.',
    'scr_people_community_mom': 'உங்கள மாதிரி வேற அம்மாக்களும் இங்க இருக்காங்க, அம்மா. கேட்கலாம், பகிரலாம்.',
    'scr_people_family_mom': 'இங்கதான் அப்பாவும் வீட்டுல இருக்குறவங்களும் நம்ம கூட சேருவாங்க, அம்மா.',
    'scr_pregnancy_journey_mom': 'இது நம்ம முழு பயணம், அம்மா. எந்த வாரம், எப்ப சந்திப்போம், அடுத்து என்ன — எல்லாம் இங்க.',
    'scr_register_pregnancy_mom': 'ஹலோ அம்மா! இங்க உங்க pregnancy-ஐ பதிவு பண்ணலாம், முக்கியமான விவரங்கள சேர்க்கலாம், உங்க pregnancy பயணத்த பின்தொடரலாம். ஒவ்வொரு அடியிலயும் எல்லாம் சரியா இருக்க நான் உதவுவேன்.',
    'scr_settings_mom': 'நான் உங்ககிட்ட எப்படி பேசணும், எத ஞாபகப்படுத்தணும் — எல்லாம் இங்க மாத்தலாம், அம்மா.',
    'screen_add_baby_birth_date_hint': 'குழந்தை பிறந்த தேதி மற்றும் நேரத்தை தேர்ந்தெடுக்கவும், அம்மா.',
    'screen_add_baby_details_hint': 'குழந்தையின் பெயர், பாலினம் மற்றும் எடை விவரங்களை நிரப்பவும், அம்மா.',
    'screen_add_baby_photo_hint': 'குழந்தையின் முதல் புகைப்படத்தை இங்கே பதிவேற்றலாம், அம்மா.',
    'screen_add_prescription_medicines_hint': 'மருந்துகளின் அளவு மற்றும் நேரங்களை சரிபார்க்கவும், அம்மா.',
    'screen_add_prescription_upload_hint': 'மருத்துவரின் மருந்துச் சீட்டை (Prescription) இங்கே படம் பிடித்து பதிவேற்றவும், அம்மா.',
    'screen_add_report_hint': 'உங்கள் மருத்துவ அறிக்கைகள் மற்றும் பரிந்துரைகளை இங்கே பதிவேற்றலாம், அம்மா.',
    'screen_agents_hint': 'திறக்க ஒரு helper-ஐ தொடுங்க, அம்மா.',
    'screen_agents_info': 'ஒவ்வொரு வசதியும் ஒரு உதவியாளர் மாதிரி, அம்மா. AlloCry, Kick Counter, Feeding Tracker, Daily Activity — ஒண்ண தொடுங்க, இல்லன்னா திறக்கச் சொல்லி என்கிட்ட கேளுங்க.',
    'screen_allobot_chat_hint': 'mic தொடுங்க, இல்ல type பண்ணுங்க, அம்மா.',
    'screen_allobot_chat_info': 'இங்க நாம பேசலாம், அம்மா. எல்லாத்தையும் நான் ஞாபகம் வெச்சுக்குவேன், நீங்க திரும்பத் திரும்ப சொல்லவே வேண்டாம்.',
    'screen_allobot_settings_hint': 'என் குரலும் வேகமும் இங்க மாத்துங்க, அம்மா.',
    'screen_allobot_settings_info': 'நான் ரொம்ப வேகமா இல்ல ரொம்ப மெதுவா பேசினா, இங்க சரி பண்ணிக்குங்க, அம்மா.',
    'screen_allocry_hint': 'என் அழுகைய பதிவு பண்ண mic தொடுங்க, அம்மா.',
    'screen_allocry_info': 'நான் அழும்போது, போன என் பக்கத்துல பிடிங்க, அம்மா. எனக்கு என்ன வேணும்னு புரிஞ்சுக்க நான் உதவுவேன்.',
    'screen_anc_care_hint': 'உங்கள் அடுத்த மருத்துவ பரிசோதனைகளை இங்கே பாருங்கள், அம்மா.',
    'screen_anc_care_info': 'உங்கள் கர்ப்பகால மருத்துவ பரிசோதனைகளை இங்கே கண்காணிக்கலாம், அம்மா.',
    'screen_ask_allo_hint': 'mic தொட்டு என்கிட்ட கேளுங்க, அம்மா.',
    'screen_ask_allo_info': 'மனசுல இருக்குறத கேளுங்க, அம்மா. என்ன பத்தி, உங்க உடம்ப பத்தி, எது வேணும்னாலும்.',
    'screen_baby_milestones_hint': 'நான் செஞ்சதும் அத தொடுங்க, அம்மா.',
    'screen_baby_milestones_info': 'ஒவ்வொரு milestone-லயும் நான் எவ்வளவு வளர்ந்திருக்கேன்னு இங்க பாக்கலாம், அம்மா.',
    'screen_baby_profile_hint': 'என் விவரம் சேர்க்க plus தொடுங்க, அம்மா.',
    'screen_baby_profile_info': 'இது முழுக்க என்னப் பத்திதான், அம்மா — என் விவரங்கள், என் தடுப்பூசிகள், என் milestones. மேலும் பாக்க எதையாவது தொடுங்க.',
    'screen_baby_vaccines_hint': 'போட்ட ஊசிய தொட்டு குறிங்க, அம்மா.',
    'screen_baby_vaccines_info': 'உங்க ஊசியும் என் ஊசியும் இங்க இருக்கு, அம்மா. ரெண்டு பேரையும் இது காப்பாத்தும்.',
    'screen_blood_glucose_analysis_hint': 'உங்கள் இரத்த சர்க்கரை அளவுகளை பாருங்கள், அம்மா.',
    'screen_blood_glucose_analysis_info': 'உங்கள் சர்க்கரை அளவை (Glucose) இங்கே கண்காணிக்கலாம், அம்மா.',
    'screen_blood_oxygen_analysis_hint': 'உங்கள் ஆக்ஸிஜன் அளவை பாருங்கள், அம்மா.',
    'screen_blood_oxygen_analysis_info': 'உங்கள் இரத்த ஆக்ஸிஜன் அளவை (SpO2) இங்கே கண்காணிக்கலாம், அம்மா.',
    'screen_blood_pressure_analysis_hint': 'உங்கள் இரத்த அழுத்த அளவுகளை பாருங்கள், அம்மா.',
    'screen_blood_pressure_analysis_info': 'உங்கள் இரத்த அழுத்தத்தை (BP) இங்கே கண்காணிக்கலாம், அம்மா.',
    'screen_children_details_hint': 'மற்ற குழந்தைகளின் விவரங்களை இங்கே சேர்க்கலாம், அம்மா.',
    'screen_daily_activity_hint': 'முடிஞ்சத குறிக்க அத தொடுங்க, அம்மா.',
    'screen_daily_activity_info': 'இன்னைக்கு இதுவரைக்கும் எப்படி போயிருக்குன்னு இங்க இருக்கு, அம்மா — என்ன முடிஞ்சுது, அடுத்து என்ன, இன்னும் என்ன பாக்கி.',
    'screen_feeding_tracker_hint': 'பால் கொடுக்கும்போது start தொடுங்க, அம்மா.',
    'screen_feeding_tracker_info': 'அம்மா, இது உங்க feeding tracker. ஒவ்வொரு தடவ பால் கொடுக்குறதையும் இங்க குறிச்சு வைக்கலாம், அப்போ நாள் முழுக்க என் feeding எப்படி இருக்குன்னு பாக்கலாம்.',
    'screen_feeds_hint': 'tip கேக்க Listen தொடுங்க, அம்மா.',
    'screen_feeds_info': 'உங்களுக்கான சின்ன டிப்ஸ், சுலபமான ரெசிபி, அம்மா. வேலை செய்யும்போதே கேளுங்க.',
    'screen_heart_rate_analysis_hint': 'உங்கள் இதயத்துடிப்பு விவரங்களை பாருங்கள், அம்மா.',
    'screen_heart_rate_analysis_info': 'உங்கள் இதயத்துடிப்பு அளவுகளை இங்கே கண்காணிக்கலாம், அம்மா.',
    'screen_home_care_info': 'இன்னைக்கு செய்ய வேண்டிய சின்ன விஷயங்க இங்க இருக்கு, அம்மா. ஒவ்வொண்ணா செய்யலாம்.',
    'screen_home_hint_mom': 'ஹலோ அம்மா! பேச mic-ஐ தொடுங்க.',
    'screen_home_info': 'இன்னைக்கு எல்லாமே இங்கதான் இருக்கு, அம்மா. சாப்பாடு, தண்ணி, ஓய்வு — நான் பாத்துக்குவேன்.',
    'screen_home_nutrition_info': 'இன்னைக்கு நீங்க சாப்பிடுறது குடிக்கிறது எல்லாம் இங்க வரும், அம்மா. சொன்னா போதும்.',
    'screen_home_vitals_info': 'உங்க உடம்போட எல்லா ரீடிங்கும் இங்க இருக்கு, அம்மா. நடை, இதயம், தூக்கம்.',
    'screen_kick_counter_hint': 'ஒவ்வொரு உதைக்கும் button தொடுங்க, அம்மா.',
    'screen_kick_counter_info': 'என் உதைகள சேர்ந்து எண்ணலாம், அம்மா. நான் அசையுறது தெரியும்போதெல்லாம் தொடுங்க.',
    'screen_log_dinner_hint': 'இரவு உணவை இங்கே பதிவு செய்யுங்கள், அம்மா.',
    'screen_log_drink_hint': 'சாப்பிட்ட பானங்கள் அல்லது பாலை இங்கே பதிவு செய்யுங்கள், அம்மா.',
    'screen_log_lunch_hint': 'மதிய உணவை இங்கே பதிவு செய்யுங்கள், அம்மா.',
    'screen_log_snacks_hint': 'சிற்றுண்டிகளை இங்கே பதிவு செய்யுங்கள், அம்மா.',
    'screen_my_cycle_phase_hint': 'period சேர்க்க log தொடுங்க, அம்மா.',
    'screen_my_cycle_phase_info': 'இப்போ உங்க உடம்புல என்ன நடக்குதுன்னு இங்க இருக்கு, அம்மா. எது நல்லது, எத தவிர்க்கணும்னு சொல்றேன். நீங்க பதிவு பண்ற ஒவ்வொரு period-ஐயும் ஞாபகம் வெச்சுக்குவேன்.',
    'screen_my_cycle_tracker_hint': 'period ஆரம்பிச்ச நாள தொடுங்க, அம்மா.',
    'screen_my_cycle_tracker_info': 'இது நம்ம cycle, அம்மா. நாட்கள நான் எண்ணிக்கிறேன், உங்க fertile days-ஐ குறிச்சு வைக்கிறேன், அடுத்த period எப்போன்னு சொல்றேன்.',
    'screen_my_health_hint': 'இன்னைக்கு நீங்க எப்படி இருக்கீங்கன்னு பாக்கலாம், அம்மா.',
    'screen_my_health_info': 'அம்மா, உங்க health எல்லாம் ஒரே இடத்துல இருக்கு — தூக்கம், இதயம், activity, சாப்பாடு. இங்க நாம சேர்ந்து பாத்துக்கலாம்.',
    'screen_my_prescriptions_hint': 'மருந்து சேர்க்க plus தொடுங்க, அம்மா.',
    'screen_my_prescriptions_info': 'உங்க மருந்துகள் எல்லாம் இங்க இருக்கு, அம்மா. ஒவ்வொரு dose நேரத்துக்கும் நான் ஞாபகப்படுத்துவேன், ஒண்ணும் விட்டுப்போகாது.',
    'screen_my_profile_hint': 'விவரம் மாத்த edit தொடுங்க, அம்மா.',
    'screen_my_profile_info': 'உங்க விவரம் எல்லாம் இங்க இருக்கு, அம்மா. சரியில்லாதத மாத்திக்குங்க.',
    'screen_my_reports_hint': 'report சேர்க்க plus தொடுங்க, அம்மா.',
    'screen_my_reports_info': 'உங்க reports எல்லாம் இங்க பத்திரமா இருக்கு, அம்மா. எப்போ வேணும்னாலும் பாக்கலாம், உங்க சொந்த Drive-லயும் backup பண்ணிக்கலாம்.',
    'screen_my_vitals_hint': 'மேலும் பாக்க எதையாவது தொடுங்க, அம்மா.',
    'screen_my_vitals_info': 'உங்க உடம்போட எல்லா ரீடிங்கும் இங்க இருக்கு, அம்மா. நடை, இதயம், தூக்கம்.',
    'screen_people_community_hint': 'அம்மாக்கள்கிட்ட கேக்க plus தொடுங்க, அம்மா.',
    'screen_people_community_info': 'உங்கள மாதிரி வேற அம்மாக்களும் இங்க இருக்காங்க, அம்மா. கேட்கலாம், பகிரலாம்.',
    'screen_people_family_hint': 'அப்பாவையும் குடும்பத்தையும் சேர்க்க invite தொடுங்க, அம்மா.',
    'screen_people_family_info': 'இங்கதான் அப்பாவும் வீட்டுல இருக்குறவங்களும் நம்ம கூட சேருவாங்க, அம்மா.',
    'screen_pregnancy_journey_hint': 'மேலும் பாக்க ஒரு வாரத்த தொடுங்க, அம்மா.',
    'screen_pregnancy_journey_info': 'இது நம்ம முழு பயணம், அம்மா. எந்த வாரம், எப்ப சந்திப்போம், அடுத்து என்ன — எல்லாம் இங்க.',
    'screen_pregnancy_vaccines_hint': 'தடுப்பூசி விவரங்களை அறிய தொடவும், அம்மா.',
    'screen_pregnancy_vaccines_info': 'கர்ப்ப காலத்தில் பரிந்துரைக்கப்பட்ட தடுப்பூசிகளை இங்கே பார்க்கலாம், அம்மா. விவரங்களை அறிய தொடவும்.',
    'screen_register_pregnancy_hint': 'விவரம் போட்டுட்டு save தொடுங்க, அம்மா.',
    'screen_register_pregnancy_info': 'ஹலோ அம்மா! இங்க உங்க pregnancy-ஐ பதிவு பண்ணலாம், முக்கியமான விவரங்கள சேர்க்கலாம், உங்க pregnancy பயணத்த பின்தொடரலாம். ஒவ்வொரு அடியிலயும் எல்லாம் சரியா இருக்க நான் உதவுவேன்.',
    'screen_reports_scans_hint': 'உங்கள் பரிசோதனை முடிவுகளை பார்க்க தொடவும், அம்மா.',
    'screen_reports_scans_info': 'உங்கள் இரத்த பரிசோதனை மற்றும் ஸ்கேன் முடிவுகளை இங்கே பார்க்கலாம், அம்மா.',
    'screen_settings_hint': 'மாத்த எதையாவது தொடுங்க, அம்மா.',
    'screen_settings_info': 'நான் உங்ககிட்ட எப்படி பேசணும், எத ஞாபகப்படுத்தணும் — எல்லாம் இங்க மாத்தலாம், அம்மா.',
