    'new_baby_dob_mom_kn': 'ನಾನು ಯಾವಾಗ ಹುಟ್ಟಿದೆ?',
    'new_baby_gender_mom': 'ನಾನು ಹುಡುಗನಾ, ಹುಡುಗಿನಾ?',
    'new_baby_gender_mom_kn': 'ನಾನು ಹುಡುಗನಾ, ಹುಡುಗಿನಾ?',
    'new_baby_name_mom': 'ನೀವು ನನಗೆ ಏನು ಹೆಸರು ಇಟ್ಟಿದ್ದೀರಿ?',
    'new_baby_name_mom_kn': 'ನೀವು ನನಗೆ ಏನು ಹೆಸರು ಇಟ್ಟಿದ್ದೀರಿ?',
    'new_baby_name_reaction_mom': 'ಎಷ್ಟು ಚೆಂದದ ಹೆಸರು. ನನಗೆ ತುಂಬಾ ಇಷ್ಟ ಆಯ್ತು.',
    'new_baby_name_reaction_mom_kn': 'ಎಷ್ಟು ಚೆಂದದ ಹೆಸರು. ನನಗೆ ತುಂಬಾ ಇಷ್ಟ ಆಯ್ತು.',
    'new_baby_saved_mom': 'ಈಗ ನನ್ನ ಬಗ್ಗೆ ಎಲ್ಲಾ ಗೊತ್ತಾಯ್ತು. ಥ್ಯಾಂಕ್ಸ್ ಅಮ್ಮ.',
    'new_baby_saved_mom_kn': 'ಈಗ ನನ್ನ ಬಗ್ಗೆ ಎಲ್ಲಾ ಗೊತ್ತಾಯ್ತು. ಥ್ಯಾಂಕ್ಸ್ ಅಮ್ಮ.',
    'new_baby_twin_mom': 'ನನಗೆ ಅವಳಿ ಇದ್ದಾರಾ? ಅವರನ್ನೂ ಇಲ್ಲಿ ಸೇರಿಸಿ.',
    'new_baby_twin_mom_kn': 'ನನಗೆ ಅವಳಿ ಇದ್ದಾರಾ? ಅವರನ್ನೂ ಇಲ್ಲಿ ಸೇರಿಸಿ.',
    'new_children_list_mom': 'ಅಮ್ಮ, ನನ್ನನ್ನ ಇಲ್ಲಿ ಸೇರಿಸಿ! ಟ್ಯಾಪ್ ಮಾಡಿ ನನ್ನ ಬಗ್ಗೆ ಎಲ್ಲಾ ಹೇಳಿ.',
    'new_children_list_mom_kn': 'ಅಮ್ಮ, ನನ್ನನ್ನ ಇಲ್ಲಿ ಸೇರಿಸಿ! ಟ್ಯಾಪ್ ಮಾಡಿ ನನ್ನ ಬಗ್ಗೆ ಎಲ್ಲಾ ಹೇಳಿ.',
    'new_feeding_intro_mom': 'ನನ್ನ feeding ಅನ್ನ ಇಲ್ಲಿ ಬರ್ಕೊಳ್ಳಬಹುದು, ನೀವು ನೆನಪಿಟ್ಕೊಳ್ಳಬೇಕಾಗಿಲ್ಲ.',
    'new_feeding_intro_mom_kn': 'ನನ್ನ feeding ಅನ್ನ ಇಲ್ಲಿ ಬರ್ಕೊಳ್ಳಬಹುದು, ನೀವು ನೆನಪಿಟ್ಕೊಳ್ಳಬೇಕಾಗಿಲ್ಲ.',
    'new_home_first_question_mom': 'ಶುರು ಮಾಡೋಣವಾ? ನೀವು ನನಗೆ ಹಾಲು ಕೊಟ್ರಾ?',
    'new_home_first_question_mom_kn': 'ಶುರು ಮಾಡೋಣವಾ? ನೀವು ನನಗೆ ಹಾಲು ಕೊಟ್ರಾ?',
    'new_home_mother_care_mom': 'ಮತ್ತೆ ಅಮ್ಮ — ನಾನು ನನ್ನನ್ನ ಮಾತ್ರ ಅಲ್ಲ, ನಿಮ್ಮನ್ನೂ ನೋಡ್ಕೊಳ್ತೀನಿ.',
    'new_home_mother_care_mom_kn': 'ಮತ್ತೆ ಅಮ್ಮ — ನಾನು ನನ್ನನ್ನ ಮಾತ್ರ ಅಲ್ಲ, ನಿಮ್ಮನ್ನೂ ನೋಡ್ಕೊಳ್ತೀನಿ.',
    'new_home_welcome_mom': 'ಅಮ್ಮ, ಇದೇ ನಮ್ಮ ಮನೆ. ನನ್ನ feeding, ನನ್ನ ನಿದ್ದೆ, ನನ್ನ ಅಳು — ಎಲ್ಲಾ ಇಲ್ಲೇ.',
    'new_home_welcome_mom_kn': 'ಅಮ್ಮ, ಇದೇ ನಮ್ಮ ಮನೆ. ನನ್ನ feeding, ನನ್ನ ನಿದ್ದೆ, ನನ್ನ ಅಳು — ಎಲ್ಲಾ ಇಲ್ಲೇ.',
