    'onb_preg_lmp_stage_t2': 'ಈಗ ನಾವು ಮಧ್ಯದ ತಿಂಗಳಲ್ಲಿದ್ದೀವಿ. ಈ ಭಾಗ ಸಾಮಾನ್ಯವಾಗಿ ಸುಲಭ ಇರುತ್ತೆ.',
