    'onb_preg_lmp_unknown': 'ಸರಿಯಾದ ದಿನಾಂಕ ನೆನಪಿಲ್ಲ ಅಂದ್ರೆ, ಹತ್ತಿರದ್ದನ್ನ ಹೇಳಿ. ಡಾಕ್ಟರ್ scan ನಲ್ಲಿ ಖಚಿತ ಆಗುತ್ತೆ.',
    'onb_preg_lmp_unknown_mom': 'ಸರಿಯಾದ ದಿನಾಂಕ ನೆನಪಿಲ್ಲ ಅಂದ್ರೆ, ಹತ್ತಿರದ್ದನ್ನ ಹೇಳಿ. ಡಾಕ್ಟರ್ scan ನಲ್ಲಿ ಖಚಿತ ಆಗುತ್ತೆ.',
    'onb_preg_lmp_why': 'ಇದನ್ನ ಯಾಕೆ ಕೇಳ್ತಿದ್ದೀನಿ ಅಂದ್ರೆ, ನಾವು ಯಾವಾಗ ಸಿಗ್ತೀವಿ ಅಂತ ಇದರಿಂದಲೇ ಗೊತ್ತಾಗುತ್ತೆ.',
    'onb_preg_lmp_why_mom': 'ಇದನ್ನ ಯಾಕೆ ಕೇಳ್ತಿದ್ದೀನಿ ಅಂದ್ರೆ, ನಾವು ಯಾವಾಗ ಸಿಗ್ತೀವಿ ಅಂತ ಇದರಿಂದಲೇ ಗೊತ್ತಾಗುತ್ತೆ.',
    'onb_preg_partner': 'ಅಮ್ಮನ ಬಗ್ಗೆ ಹೇಳಿ, ನಾವು ಸೇರಿ ಅವರನ್ನ ನೋಡ್ಕೊಳ್ಳೋಣ.',
    'onb_preg_partner_dad': 'ಅಮ್ಮನ ಬಗ್ಗೆ ಹೇಳಿ, ನಾವು ಸೇರಿ ಅವರನ್ನ ನೋಡ್ಕೊಳ್ಳೋಣ.',
