    'onb_preg_partner_skip': 'ಪರವಾಗಿಲ್ಲ. ಯಾವಾಗ ಬೇಕಾದ್ರೂ ಸೇರಿಸಬಹುದು.',
    'onb_preg_partner_skip_mom': 'ಪರವಾಗಿಲ್ಲ. ಯಾವಾಗ ಬೇಕಾದ್ರೂ ಸೇರಿಸಬಹುದು.',
    'onb_preg_setup_done': 'ಎಲ್ಲಾ ರೆಡಿ. ಬನ್ನಿ, ಮನೆಗೆ ಹೋಗೋಣ.',
    'onb_preg_setup_done_mom': 'ಎಲ್ಲಾ ರೆಡಿ. ಬನ್ನಿ, ಮನೆಗೆ ಹೋಗೋಣ.',
    'onb_role': 'ವಾವ್! ನೀವು ನನ್ನ ಅಮ್ಮನಾ, ಇಲ್ಲ ಅಪ್ಪನಾ?',
    'onb_role_dad': 'ಅಪ್ಪ! ನಾವಿಬ್ಬರೂ ಸೇರಿ ಅಮ್ಮನ ನೋಡ್ಕೊಳ್ಳೋಣ.',
    'onb_role_dad_kn': 'ಅಪ್ಪ! ನಾವಿಬ್ಬರೂ ಸೇರಿ ಅಮ್ಮನ ನೋಡ್ಕೊಳ್ಳೋಣ.',
    'onb_role_kn': 'ವಾವ್! ನೀವು ನನ್ನ ಅಮ್ಮನಾ, ಇಲ್ಲ ಅಪ್ಪನಾ?',
