    'pre_cycle_saved_mom': 'ಸೇವ್ ಆಯ್ತು. ನಿಮ್ಮ fertile ದಿನಗಳನ್ನ ಮತ್ತು ಮುಂದಿನ period ದಿನಾಂಕವನ್ನ ಹೇಳ್ತೀನಿ.',
