    'pre_habits_mom': 'ಒಳ್ಳೆ ಊಟ, ಒಳ್ಳೆ ನಿದ್ದೆ, ತಂಬಾಕು ಮದ್ಯ ಬೇಡ. ಹೀಗೇ ನನಗಾಗಿ ತಯಾರಾಗಬೇಕು.',
    'pre_habits_mom_kn': 'ಒಳ್ಳೆ ಊಟ, ಒಳ್ಳೆ ನಿದ್ದೆ, ತಂಬಾಕು ಮದ್ಯ ಬೇಡ. ಹೀಗೇ ನನಗಾಗಿ ತಯಾರಾಗಬೇಕು.',
    'pre_home_first_question_mom': 'ಶುರು ಮಾಡೋಣವಾ? ಇವತ್ತು ನೀವು ಹೇಗಿದ್ದೀರಿ?',
