    'onb_pre_habits_mom': 'સારું ખાવાનું, સારી ઊંઘ, અને તમાકુ કે દારૂ બિલકુલ નહીં. આ રીતે જ મારા માટે તૈયારી થશે.',
    'onb_pre_home_first_question': 'શરૂ કરીએ? આજે તમને કેવું લાગે છે?',
