    'onb_preg_lmp_stage_t1': 'આપણે શરૂઆતના મહિનાઓમાં છીએ. મારું કદ હજી બહુ નાનું છે.',
    'onb_preg_lmp_stage_t1_mom': 'આપણે શરૂઆતના મહિનાઓમાં છીએ. મારું કદ હજી બહુ નાનું છે.',
