    'onb_status_newmom_gu': 'હું તો પહેલેથી જ તમારા ખોળામાં છું! ચાલો, સાથે મળીને મારું ધ્યાન રાખીએ.',
    'onb_status_newmom_mom': 'હું તો પહેલેથી જ તમારા ખોળામાં છું! ચાલો, સાથે મળીને મારું ધ્યાન રાખીએ.',
    'onb_status_pregnant': 'તમે અત્યારે મને પેટમાં લઈને છો! હું અહીં જ તમારી સાથે છું.',
    'onb_status_pregnant_mom': 'તમે અત્યારે મને પેટમાં લઈને છો! હું અહીં જ તમારી સાથે છું.',
    'onb_status_pregnant_mom_gu': 'તમે અત્યારે મને પેટમાં લઈને છો! હું અહીં જ તમારી સાથે છું.',
    'onb_status_prepregnancy': 'તમે મારા માટે તૈયારી કરો છો. હું તમારી પાસે આવવાની રાહ જોઉં છું.',
    'onb_status_prepregnancy_mom': 'તમે મારા માટે તૈયારી કરો છો. હું તમારી પાસે આવવાની રાહ જોઉં છું.',
    'onb_status_prepregnancy_mom_gu': 'તમે મારા માટે તૈયારી કરો છો. હું તમારી પાસે આવવાની રાહ જોઉં છું.',
    'onb_voice_lang': 'હું તમારી સાથે કઈ ભાષામાં વાત કરું?',
    'onb_voice_lang_gu': 'હું તમારી સાથે કઈ ભાષામાં વાત કરું?',
    'pre_cycle_irregular_mom': 'નિયમિત ન હોય તો પણ વાંધો નહીં. યાદ હોય એટલું કહો, આપણે સાથે સમજી લઈશું.',
    'pre_cycle_irregular_mom_gu': 'નિયમિત ન હોય તો પણ વાંધો નહીં. યાદ હોય એટલું કહો, આપણે સાથે સમજી લઈશું.',
    'pre_cycle_length_mom': 'સામાન્ય રીતે તમારું cycle કેટલા દિવસનું હોય છે?',
    'pre_cycle_length_mom_gu': 'સામાન્ય રીતે તમારું cycle કેટલા દિવસનું હોય છે?',
    'pre_cycle_mom': 'મમ્મી, તમારું છેલ્લું માસિક ક્યારે શરૂ થયું હતું?',
    'pre_cycle_mom_gu': 'મમ્મી, તમારું છેલ્લું માસિક ક્યારે શરૂ થયું હતું?',
    'pre_cycle_saved_mom': 'સાચવી લીધું. હું તમને તમારા fertile દિવસો અને આવતા માસિકની તારીખ કહીશ.',
    'pre_cycle_saved_mom_gu': 'સાચવી લીધું. હું તમને તમારા fertile દિવસો અને આવતા માસિકની તારીખ કહીશ.',
    'pre_folic_acid_mom': 'એક જરૂરી વાત. અત્યારથી જ folic acid લેવાનું શરૂ કરો — હું આવું એ પહેલાં જ એ મને સુરક્ષિત રાખે છે.',
    'pre_folic_acid_mom_gu': 'એક જરૂરી વાત. અત્યારથી જ folic acid લેવાનું શરૂ કરો — હું આવું એ પહેલાં જ એ મને સુરક્ષિત રાખે છે.',
    'pre_habits_mom': 'સારું ખાવાનું, સારી ઊંઘ, અને તમાકુ કે દારૂ બિલકુલ નહીં. આ રીતે જ મારા માટે તૈયારી થશે.',
    'pre_habits_mom_gu': 'સારું ખાવાનું, સારી ઊંઘ, અને તમાકુ કે દારૂ બિલકુલ નહીં. આ રીતે જ મારા માટે તૈયારી થશે.',
    'pre_home_first_question_mom': 'શરૂ કરીએ? આજે તમને કેવું લાગે છે?',
    'pre_home_first_question_mom_gu': 'શરૂ કરીએ? આજે તમને કેવું લાગે છે?',
    'pre_home_waiting_mom': 'હું તમારી પાસે આવવાની રાહ જોઉં છું. ચાલો, સાથે તૈયારી કરીએ.',
    'pre_home_waiting_mom_gu': 'હું તમારી પાસે આવવાની રાહ જોઉં છું. ચાલો, સાથે તૈયારી કરીએ.',
    'pre_home_welcome_mom': 'મમ્મી, આ જ આપણું ઘર. હું તમારી તારીખો યાદ રાખીશ અને તમારું ધ્યાન રાખીશ.',
    'pre_home_welcome_mom_gu': 'મમ્મી, આ જ આપણું ઘર. હું તમારી તારીખો યાદ રાખીશ અને તમારું ધ્યાન રાખીશ.',
    'pre_kids_mom': 'તમને પહેલેથી બાળકો છે?',
    'pre_kids_mom_gu': 'તમને પહેલેથી બાળકો છે?',
    'pre_partner_mom': 'તમારા સાથી વિશે કહો, જેથી બંને મળીને મારા માટે તૈયારી કરી શકો.',
