    'pre_setup_done_mom_gu': 'બધું તૈયાર છે. ચાલો, ઘરે જઈએ.',
    'preg_edd_bubble_mom': 'વાહ! એ જ દિવસે આપણે મળીશું. બહુ આતુરતા છે!',
