    'preg_edd_countdown_half_mom_gu': 'અડધાથી વધારે થઈ ગયું. દિવસો પસાર થઈ રહ્યા છે.',
    'preg_edd_countdown_near_mom': 'હવે વધારે દિવસ બાકી નથી. મારી તૈયારી ચાલી રહી છે.',
    'preg_edd_countdown_near_mom_gu': 'હવે વધારે દિવસ બાકી નથી. મારી તૈયારી ચાલી રહી છે.',
    'preg_edd_countdown_soon_mom': 'હવે બહુ જલ્દી. કોઈ પણ દિવસે હું તમારા ખોળામાં હોઈશ.',
    'preg_edd_countdown_soon_mom_gu': 'હવે બહુ જલ્દી. કોઈ પણ દિવસે હું તમારા ખોળામાં હોઈશ.',
