    'preg_edd_doctor_date_mom': 'ડૉક્ટરે અલગ તારીખ આપી હોય, તો એ જ કહો.',
    'preg_edd_doctor_date_mom_gu': 'ડૉક્ટરે અલગ તારીખ આપી હોય, તો એ જ કહો.',
    'preg_edd_saved_mom': 'સાચવી લીધું. હું તમારી સાથે દિવસ ગણીશ.',
    'preg_edd_saved_mom_gu': 'સાચવી લીધું. હું તમારી સાથે દિવસ ગણીશ.',
    'preg_home_first_question_mom': 'શરૂ કરીએ? આજે તમે કંઈ ખાધું?',
    'preg_home_first_question_mom_gu': 'શરૂ કરીએ? આજે તમે કંઈ ખાધું?',
    'preg_home_mic_hint_mom': 'મારી સાથે વાત કરવી હોય ત્યારે mic દબાવો અને બોલો.',
    'preg_home_mic_hint_mom_gu': 'મારી સાથે વાત કરવી હોય ત્યારે mic દબાવો અને બોલો.',
    'preg_home_welcome_mom': 'મમ્મી, આ જ આપણું ઘર. હું રોજ અહીં જ તમારા માટે હોઈશ.',
    'preg_home_welcome_mom_gu': 'મમ્મી, આ જ આપણું ઘર. હું રોજ અહીં જ તમારા માટે હોઈશ.',
    'preg_kids_mom': 'મને પહેલેથી મોટો ભાઈ કે મોટી બહેન છે?',
    'preg_kids_mom_gu': 'મને પહેલેથી મોટો ભાઈ કે મોટી બહેન છે?',
    'preg_kids_no_mom': 'એટલે હું તમારું પહેલું બાળક! આ વધારે ખાસ થઈ ગયું.',
    'preg_kids_no_mom_gu': 'એટલે હું તમારું પહેલું બાળક! આ વધારે ખાસ થઈ ગયું.',
    'preg_kids_yes_mom': 'કેટલું સરસ! એટલે મને સંગાથ છે.',
    'preg_kids_yes_mom_gu': 'કેટલું સરસ! એટલે મને સંગાથ છે.',
    'preg_lmp_confirm_mom': 'થઈ ગયું! હવે આપણે કયા અઠવાડિયામાં છીએ એ ખબર પડી ગઈ.',
    'preg_lmp_confirm_mom_gu': 'થઈ ગયું! હવે આપણે કયા અઠવાડિયામાં છીએ એ ખબર પડી ગઈ.',
    'preg_lmp_future_error_mom': 'આ તારીખ આજ પછીની છે. એક વાર જોઈ લો.',
    'preg_lmp_future_error_mom_gu': 'આ તારીખ આજ પછીની છે. એક વાર જોઈ લો.',
    'preg_lmp_mom': 'મમ્મી, તમારું છેલ્લું માસિક ક્યારે શરૂ થયું હતું?',
    'preg_lmp_mom_gu': 'મમ્મી, તમારું છેલ્લું માસિક ક્યારે શરૂ થયું હતું?',
    'preg_lmp_stage_t1_mom': 'આપણે શરૂઆતના મહિનાઓમાં છીએ. મારું કદ હજી બહુ નાનું છે.',
    'preg_lmp_stage_t1_mom_gu': 'આપણે શરૂઆતના મહિનાઓમાં છીએ. મારું કદ હજી બહુ નાનું છે.',
    'preg_lmp_stage_t2_mom': 'હવે આપણે વચ્ચેના મહિનાઓમાં છીએ. આ ભાગ સામાન્ય રીતે સૌથી સહેલો હોય છે.',
    'preg_lmp_stage_t2_mom_gu': 'હવે આપણે વચ્ચેના મહિનાઓમાં છીએ. આ ભાગ સામાન્ય રીતે સૌથી સહેલો હોય છે.',
    'preg_lmp_stage_t3_mom': 'આપણે છેલ્લા મહિનાઓમાં પહોંચી ગયા છીએ. હવે વધારે વાર નથી.',
    'preg_lmp_stage_t3_mom_gu': 'આપણે છેલ્લા મહિનાઓમાં પહોંચી ગયા છીએ. હવે વધારે વાર નથી.',
    'preg_lmp_unknown_mom': 'ચોક્કસ તારીખ યાદ ન હોય તો નજીકની કહો. ડૉક્ટરનું scan ખાતરી કરી આપશે.',
