    'preg_partner_dad': 'મમ્મી વિશે કહો, જેથી આપણે સાથે મળીને એમનું ધ્યાન રાખીએ.',
    'preg_partner_dad_gu': 'મમ્મી વિશે કહો, જેથી આપણે સાથે મળીને એમનું ધ્યાન રાખીએ.',
    'preg_partner_mom': 'પપ્પા વિશે કહો, જેથી તેઓ પણ આપણી સફરમાં જોડાય.',
